SELECT a.day AS "数据日期",a.channel AS "渠道ID",a.battle_type AS "玩法类型",a.battle_type_name AS "玩法名称",a.map_id AS "关卡ID",a.starts AS "进入次数",a.entry_users AS "进入人数",a.passes AS "通关次数",a.pass_users AS "通关人数",a.failures AS "失败次数",a.fail_users AS "失败人数",CAST(ROUND(a.failures*1.000000000000/NULLIF(a.fail_users,0),2) AS decimal(18,2)) AS "人均失败次数",a.exits AS "退出次数",a.exit_users AS "退出人数",a.replays AS "重玩次数",a.replay_users AS "重玩人数",CAST(ROUND(a.pass_users*1.000000000000/NULLIF(a.entry_users,0),4) AS decimal(18,4)) AS "通关率",IF(a.next_users IS NULL,NULL,CAST(ROUND((a.entry_users-a.next_users)*1.000000000000/NULLIF(a.entry_users,0),4) AS decimal(18,4))) AS "驻留率",CAST(ROUND(a.entry_users*1.000000000000/NULLIF(COALESCE(a.prev_users,b.base_users),0),4) AS decimal(18,4)) AS "关卡转化率",CAST(ROUND(a.entry_users*1.000000000000/NULLIF(b.base_users,0),4) AS decimal(18,4)) AS "总转化率",b.base_users AS "转化率基数人数" FROM (SELECT a.*,LAG(entry_users) OVER(PARTITION BY day,channel,battle_type,battle_type_name ORDER BY map_id NULLS LAST) prev_users,LEAD(entry_users) OVER(PARTITION BY day,channel,battle_type,battle_type_name ORDER BY map_id NULLS LAST) next_users FROM (SELECT day,channel,battle_type,battle_type_name,map_id,COUNT_IF(event_name='battle_start') starts,COUNT(DISTINCT IF(event_name='battle_start',pid,NULL)) entry_users,COUNT_IF(event_name='battle_result' AND battle_result=1) passes,COUNT(DISTINCT IF(event_name='battle_result' AND battle_result=1,pid,NULL)) pass_users,COUNT_IF(event_name='battle_result' AND battle_result=2) failures,COUNT(DISTINCT IF(event_name='battle_result' AND battle_result=2,pid,NULL)) fail_users,COUNT_IF(event_name='battle_result' AND battle_result=3) exits,COUNT(DISTINCT IF(event_name='battle_result' AND battle_result=3,pid,NULL)) exit_users,COUNT_IF(event_name='battle_result' AND battle_result=4) replays,COUNT(DISTINCT IF(event_name='battle_result' AND battle_result=4,pid,NULL)) replay_users FROM (SELECT f.*,CASE WHEN s.scope=0 THEN '全部渠道' ELSE reg_channel END channel FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id reg_channel,e."$part_event" event_name,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.battle_result,e.battle_time,e.remain_screw_num FROM ta.v_event_54 e JOIN (SELECT "#user_id",coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid,date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day,coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) f WHERE ${Selector:selector2}) f CROSS JOIN (VALUES (0),(1)) s(scope)) f WHERE event_name IN ('battle_start','battle_result') GROUP BY 1,2,3,4,5) a) a LEFT JOIN (SELECT day,channel,COUNT(DISTINCT pid) base_users FROM (SELECT f.*,CASE WHEN s.scope=0 THEN '全部渠道' ELSE reg_channel END channel FROM (SELECT * FROM (SELECT e."$part_date" day,u.pid,u.reg_day,u.channel_id reg_channel,e."$part_event" event_name,coalesce(e.battle_type,'未知模式') battle_type,coalesce(nullif(e.battle_type_name,''),e.battle_type,'未知模式') battle_type_name,e.map_id,e.battle_result,e.battle_time,e.remain_screw_num FROM ta.v_event_54 e JOIN (SELECT "#user_id",coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid,date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day,coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1}) f WHERE ${Selector:selector2}) f CROSS JOIN (VALUES (0),(1)) s(scope)) f  GROUP BY 1,2) b ON a.day=b.day AND a.channel=b.channel WHERE ('${Variable3}'='全部' OR a.map_id=TRY_CAST('${Variable3}' AS double)) ORDER BY a.day DESC,a.channel,a.battle_type,a.map_id